float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
  vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;
  float t=iTime;
  float hor=-0.08;
  vec3 col;
  if(uv.y>hor){
    float sy=uv.y-hor;
    col=mix(vec3(0.95,0.35,0.35),vec3(0.55,0.08,0.45),smoothstep(0.0,0.18,sy));
    col=mix(col,vec3(0.04,0.01,0.12),smoothstep(0.15,0.6,sy));
    // stars
    vec2 sg=floor(fragCoord/3.0);
    float h=hash(sg);
    if(h>0.997) col+=vec3(0.8,0.8,1.0)*smoothstep(0.15,0.45,sy)*(0.5+0.5*sin(t*3.0+h*100.0));
    // sun
    float r=0.27;
    float ph=fract(t/16.0);
    vec2 sc=vec2(0.0,hor+0.32-ph*0.65);
    float d=length(uv-sc)-r;
    float ry=(uv.y-sc.y)/r;
    vec3 sunCol=mix(vec3(1.0,0.15,0.55),vec3(1.0,0.9,0.25),clamp(ry*0.5+0.6,0.0,1.0));
    float mask=1.0-smoothstep(-0.002,0.002,d);
    if(ry<0.25){
      float s=fract(ry*7.0+t*0.6);
      float gap=mix(0.05,0.65,clamp((0.25-ry)/1.25,0.0,1.0));
      mask*=smoothstep(gap-0.03,gap+0.03,s);
    }
    col+=sunCol*exp(-max(d,0.0)*7.0)*0.45;
    col=mix(col,sunCol*1.2,mask);
    // mountains
    float ax=abs(uv.x);
    float mh=(0.06+0.035*sin(uv.x*5.0+1.3)+0.02*sin(uv.x*13.0+0.5)+0.01*sin(uv.x*31.0))*smoothstep(0.12,0.7,ax);
    if(sy<mh){
      vec3 mc=vec3(0.08,0.02,0.15);
      float rim=exp(-(mh-sy)*60.0);
      mc+=vec3(1.0,0.2,0.7)*rim*0.6;
      col=mc;
    }
  } else {
    float dy=hor-uv.y;
    float z=0.35/dy;
    float wx=uv.x*z;
    float wz=z+t*3.0;
    vec2 g=vec2(wx,wz);
    vec2 fw=max(fwidth(g),vec2(1e-4));
    vec2 gd=abs(fract(g)-0.5);
    gd=(0.5-gd)/fw; // distance to line in pixels
    float l=max(exp(-gd.x*0.6),exp(-gd.y*0.6));
    float fade=smoothstep(0.0,0.12,dy);
    col=mix(vec3(0.05,0.0,0.1),vec3(0.25,0.03,0.25),exp(-dy*8.0));
    vec3 lc=mix(vec3(1.0,0.2,0.8),vec3(0.2,0.9,1.0),smoothstep(0.0,0.5,dy));
    col+=lc*l*fade*1.4;
    col+=lc*0.15*fade*max(exp(-gd.x*0.15),exp(-gd.y*0.15));
    // sun reflection
    float ph=fract(t/16.0);
    float vis=smoothstep(-0.25,0.15,0.32-ph*0.65);
    col+=vec3(1.0,0.3,0.5)*exp(-abs(uv.x)*6.0)*exp(-dy*10.0)*0.4*vis;
    col+=vec3(1.0,0.4,0.7)*exp(-dy*40.0)*0.8;
  }
  // horizon haze line
  col+=vec3(1.0,0.45,0.75)*exp(-abs(uv.y-hor)*90.0)*0.7;
  // vignette
  vec2 q=fragCoord/iResolution.xy;
  col*=0.6+0.4*pow(16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.25);
  col=1.0-exp(-col*1.3);
  col=pow(col,vec3(0.9));
  fragColor=vec4(col,1.0);
}

